    /// <summary>
    /// Get the warhouse quantity for the item
    /// </summary>
    ///<params> Purchase line</params>
    ///<returns>
    ///warehouse quantity
    ///</returns>
    private Qty getWarehouseQty(PurchLine purchlineLoc)
    {
        MetItemSiteSettingsSetup        itemSiteSettingSetup;
        InventDim                       inventDim;
        UnitOfMeasureConversion         unitOfMeasureConversion;
        UnitOfMeasureSymbol             unitIDFrom;
        UnitOfMeasureSymbol             unitIDTo;
        UnitOfMeasureConversionFactor   conversionFactor;
        Qty                             warehouseQty;

        select firstonly UnitId from itemSiteSettingSetup
            where itemSiteSettingSetup.ItemId == purchLineLoc.ItemId
                join InventDim
                    where inventDim.inventDimId == purchLineLoc.InventDimId
                       && inventDim.InventSiteId == itemSiteSettingSetup.InventSiteId;

        unitIDFrom = itemSiteSettingSetup.UnitId;
        unitIDTo = purchlineLoc.PurchUnit;

        if(unitIDFrom == unitIDTo)
        {
            warehouseQty = any2int(this.OrderedPurchaseQuantity);
        }
        else
        {
            conversionFactor = roundUp(UnitOfMeasureConversion::findByConversion(
                UnitOfMeasure::findBySymbol(unitIDFrom).RecId,
                UnitOfMeasure::findBySymbol(unitIDTo).RecId,
                EcoResProduct::findByProductNumber(purchLineLoc.ItemId).RecId)
                .Factor, 0);

            if(conversionFactor != 0)
            {
                warehouseQty = any2int(this.OrderedPurchaseQuantity / conversionFactor);
            }
            else
            {
                conversionFactor = roundUp(UnitOfMeasureConversion::findByConversion(
                UnitOfMeasure::findBySymbol(unitIDTo).RecId,
                UnitOfMeasure::findBySymbol(unitIDFrom).RecId,
                EcoResProduct::findByProductNumber(purchLineLoc.ItemId).RecId)
                .Factor, 0);

                if(conversionFactor != 0)
                {
                    warehouseQty = any2int(this.OrderedPurchaseQuantity * conversionFactor);
                }
                else
                {
                    warehouseQty = this.OrderedPurchaseQuantity;
                }
            }
        }
        return warehouseQty;
    }
